    HOUSE_SN, AMENITY_SN, REG_DT, MDFCN_DT, RGTR_SN
) VALUES (
    #{houseSn}, #{amenitySn}, UTC_TIMESTAMP(6), UTC_TIMESTAMP(6), #{rgtrSn}
