mapper.update:
UPDATE HOUSE_AMENITY HA
  JOIN HOUSE H ON H.HOUSE_SN = HA.HOUSE_SN AND H.PRTNR_SN = #{prtnrSn} AND H.DEL_YN = 'N'
   SET HA.DEL_YN = 'Y',
       HA.MDFCN_DT = UTC_TIMESTAMP(6),
       HA.MDFR_SN = #{mdfrSn}
 WHERE HA.HOUSE_SN = #{houseSn}
   AND HA.DEL_YN = 'N'

   AND HA.AMENITY_SN NOT IN
    #{id}
